window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e41602f271ab7dd5"]={"versions": [{"id": "FIG-e41602f271ab7dd5", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Veranschaulichung der Modellstruktur und Paketierung von AUTOSAR-M1-Elementen im Kontext des Modell- und Datenaustauschs zwischen Werkzeugen (Interoperability of AUTOSAR Tools).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt Instanzen von Modellelementen und deren Beziehungen dar:</p>\n<ul class=\"fig-list\"><li><code>:ARPackage</code> mit Attribut <code>shortName = OEM</code> aggregiert über die Kompositionsrolle <code>+element</code> die Instanz <code>:ApplicationPrimitiveDataType</code> (<code>shortName = velocityType</code>).\n</li><li><code>:ApplicationPrimitiveDataType</code> aggregiert über <code>+invalidValue</code> eine <code>:NumericalValueSpecification</code> (<code>value = 10000</code>) sowie über <code>+displayFormat</code> einen <code>:DisplayFormatString</code> (<code>value = %f6.2</code>).\n</li><li>Ein weiteres separates <code>:ARPackage</code> mit Attribut <code>shortName = supplier</code> aggregiert über die Kompositionsrolle <code>+elements</code> die Instanz <code>:SenderReceiverInterface</code> (<code>isService = false</code>, <code>shortName = interface</code>).\n</li><li><code>:SenderReceiverInterface</code> aggregiert über <code>+dataElement</code> die Instanz <code>:VariableDataPrototype</code> (<code>shortName = velocity</code>).\n</li><li><code>:VariableDataPrototype</code> referenziert über die Assoziationsrolle <code>+type</code> das <code>:ApplicationPrimitiveDataType</code> (<code>velocityType</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Laufzeitsequenzen. Es illustriert den Zustand eines AUTOSAR-Modells, bei dem ein Schnittstellenelement (<code>SenderReceiverInterface</code>) in ein anderes Paket (<code>supplier</code>) verschoben wurde, während der referenzierte Datentyp im ursprünglichen Paket (<code>OEM</code>) verbleibt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für AUTOSAR-Werkzeugketten beim Verschieben von Modellelementen zwischen <code>ARPackage</code>-Containern:</p>\n<ul class=\"fig-list\"><li>Durch das Verschieben eines Elements ändern sich die Enthaltenseins-Listen (<code>+elements</code> bzw. <code>+element</code>) des Quell- und Zielpakets.\n</li><li>Da AUTOSAR absolute Referenzen über hierarchische Short-Name-Pfade auflöst, müssen alle absoluten Referenzen, die auf verschobene Elemente verweisen, werkzeugseitig aktualisiert werden.\n</li><li>Paketgrenzen (<code>OEM</code> vs. <code>supplier</code>) verdeutlichen die Auswirkung auf getrennte Lieferumfänge und Paketstrukturen beim organisationsübergreifenden Modellaustausch.\n</li></ul>"}, {"id": "FIG-d7c24d57f1f8a50c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Veranschaulichung der Modellstruktur und Paketierung von AUTOSAR-M1-Elementen im Kontext des Modell- und Datenaustauschs zwischen Werkzeugen (Interoperability of AUTOSAR Tools).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt Instanzen von Modellelementen und deren Beziehungen dar:</p>\n<ul class=\"fig-list\"><li><code>:ARPackage</code> mit Attribut <code>shortName = OEM</code> aggregiert über die Kompositionsrolle <code>+element</code> die Instanz <code>:ApplicationPrimitiveDataType</code> (<code>shortName = velocityType</code>).\n</li><li><code>:ApplicationPrimitiveDataType</code> aggregiert über <code>+invalidValue</code> eine <code>:NumericalValueSpecification</code> (<code>value = 10000</code>) sowie über <code>+displayFormat</code> einen <code>:DisplayFormatString</code> (<code>value = %f6.2</code>).\n</li><li>Ein weiteres separates <code>:ARPackage</code> mit Attribut <code>shortName = supplier</code> aggregiert über die Kompositionsrolle <code>+elements</code> die Instanz <code>:SenderReceiverInterface</code> (<code>isService = false</code>, <code>shortName = interface</code>).\n</li><li><code>:SenderReceiverInterface</code> aggregiert über <code>+dataElement</code> die Instanz <code>:VariableDataPrototype</code> (<code>shortName = velocity</code>).\n</li><li><code>:VariableDataPrototype</code> referenziert über die Assoziationsrolle <code>+type</code> das <code>:ApplicationPrimitiveDataType</code> (<code>velocityType</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Laufzeitsequenzen. Es illustriert den Zustand eines AUTOSAR-Modells, bei dem ein Schnittstellenelement (<code>SenderReceiverInterface</code>) in ein anderes Paket (<code>supplier</code>) verschoben wurde, während der referenzierte Datentyp im ursprünglichen Paket (<code>OEM</code>) verbleibt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für AUTOSAR-Werkzeugketten beim Verschieben von Modellelementen zwischen <code>ARPackage</code>-Containern:</p>\n<ul class=\"fig-list\"><li>Durch das Verschieben eines Elements ändern sich die Enthaltenseins-Listen (<code>+elements</code> bzw. <code>+element</code>) des Quell- und Zielpakets.\n</li><li>Da AUTOSAR absolute Referenzen über hierarchische Short-Name-Pfade auflöst, müssen alle absoluten Referenzen, die auf verschobene Elemente verweisen, werkzeugseitig aktualisiert werden.\n</li><li>Paketgrenzen (<code>OEM</code> vs. <code>supplier</code>) verdeutlichen die Auswirkung auf getrennte Lieferumfänge und Paketstrukturen beim organisationsübergreifenden Modellaustausch.\n</li></ul>"}], "trans": [{"from": "FIG-e41602f271ab7dd5", "to": "FIG-d7c24d57f1f8a50c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Alle Objektkästen: Trennlinien zwischen Bezeichner-/Klassenbereich (oben) und Attributbereich (unten) eingefügt.\n</li><li>Layout der Boxen: Leicht veränderte Rahmen- und Textabstände durch Neu-Rendering.\n</li></ul>"}]};
